import json
for name in ['pruned_standard_20', 'pruned_rasp_20', 'pruned_standard_25', 'pruned_rasp_25']:
    try:
        cfg = json.load(open(f'/root/autodl-tmp/{name}/config.json'))
        print(f'{name}:')
        for k in ['num_attention_heads', 'num_key_value_heads', 'hidden_size', 'intermediate_size']:
            print(f'  {k}={cfg.get(k, \"N/A\")}')
        for k in ['per_layer_num_attention_heads', 'per_layer_num_key_value_heads']:
            if k in cfg:
                print(f'  {k}={cfg[k]}')
        print()
    except Exception as e:
        print(f'{name}: ERROR {e}')
"
